/**
 * Sampel tembakan asli (rekaman lapangan, lisensi CC0 / CC-BY) yang di-embed sebagai
 * data URI supaya ikut ter-inline di bundel single-file. Didecode sekali oleh
 * AudioContext.decodeAudioData lalu dipakai ulang dengan pitch & gain acak.
 *
 * pistol9mm : 9 mm handgun report (Mike Koenig / SoundBible, CC BY 3.0)
 * pistolAlt : handgun report alternatif (Freesound 686351, CC0)
 * rifle     : automatic rifle report (Freesound 519623, CC0)
 * shotgun   : smoothbore 12-gauge style blast, open range (Freesound 687399, CC0)
 */

const GUN_SAMPLE_PISTOL9MM = "data:audio/wav;base64,";
const GUN_SAMPLE_PISTOLALT = "data:audio/mpeg;base64,";
const GUN_SAMPLE_RIFLE = "data:audio/mpeg;base64,";
const GUN_SAMPLE_SHOTGUN = "data:audio/mpeg;base64,";

export const GUN_SAMPLES: Record<string, string> = {
  pistol9mm: GUN_SAMPLE_PISTOL9MM,
  pistolAlt: GUN_SAMPLE_PISTOLALT,
  rifle: GUN_SAMPLE_RIFLE,
  shotgun: GUN_SAMPLE_SHOTGUN,
};
